app.post('/users', (req, res) => {
  // Validate that name field exists and is a string
  if (!req.body.name) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Name field is required'
    });
  }

  if (typeof req.body.name !== 'string') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Name field must be a string'
    });
  }

  // If validation passes, return success response
  res.status(201).json({
    message: `User ${req.body.name} created successfully`,
    name: req.body.name
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

